const [showForm, setShowForm] = useState(null);
const [formData, setFormData] = useState({
  title: "",
  description: "",
  due_date: ""
});

const createAssignment = async (courseId) => {
  try {
    const res = await axios.post("/api/assignments", {
      course_id: courseId,
      ...formData
    });

    if (res.data.success) {
      alert("Assignment created ✅");
      setShowForm(null);
      setFormData({ title: "", description: "", due_date: "" });
    }
  } catch (err) {
    console.log(err);
  }
};

import { useEffect, useState } from "react";
import axios from "axios";

export default function TeacherCourses() {
  const [courses, setCourses] = useState([]);

  useEffect(() => {
    axios
      .get("/api/teachers/1/courses")
      .then((res) => {
        console.log("DATA:", res.data); // debug
        setCourses(res.data);
      })
      .catch((err) => console.log(err));
  }, []);

  return (
    <div className="p-6">
      <h1 className="text-xl font-bold mb-4">
        Teacher Courses Page
      </h1>

      {courses.length === 0 ? (
        <p className="text-gray-500">No courses found</p>
      ) : (
        courses.map((course) => (
          <div
            key={course.course_id}
            className="bg-white p-4 rounded shadow mb-4 border"
          >
            <h2 className="text-lg font-semibold">
              {course.course_name}
            </h2>

            <p className="text-sm text-gray-600">
              Code: {course.course_code}
            </p>

            <p className="text-sm text-gray-600">
              Duration: {course.duration_weeks} weeks
            </p>

            <p className="text-sm">
              Difficulty: {course.difficulty_level}
            </p>

            <div className="mt-2 text-sm text-gray-700">
              👨‍🎓 Students: {course.student_count} <br />
              📝 Assignments: {course.assignment_count} <br />
              ❓ Quizzes: {course.quiz_count}
            </div>
          </div>
        ))
      )}
    </div>
  );
}
